 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);c=b.new_context(viewport={'width':390,'height':844},reduced_motion='reduce');c.route('**/ink/art/appearance/**',lambda r:r.abort());c.route('**/*.supabase.co/**',lambda r:r.abort());page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE+'?battle-preview=unified&kind=event');page.wait_for_function('!!window.__martialBattleStage');result=page.evaluate('''async()=>{const{loadAppearanceAssets,prepareAppearance}=await import('/src/appearance/assets.ts'),{drawAppearance}=await import('/src/appearance/model.ts');const assets=await loadAppearanceAssets(),a={head:'bun',outfit:'cloak',tone:'cinnabar'};await prepareAppearance(assets,a);const c=document.createElement('canvas');c.width=500;c.height=500;const x=c.getContext('2d');const outputs=[];for(const time of [.02,.2,.48,.7]){x.clearRect(0,0,500,500);drawAppearance(x,assets,a,{x:250,y:475,height:360,pose:'attack',time,reduced:true});outputs.push(c.toDataURL());}let n=0;for(let i=3,d=x.getImageData(0,0,500,500).data;i<d.length;i+=4)if(d[i]>100)n++;return{sameIdentity:a,simplified:assets.simplified,opaque:n,reducedPixelStable:outputs.every(v=>v===outputs[0])}}''');assert result['simplified'] and result['opaque']>500 and result['reducedPixelStable'] and not errors;result['pageerrors']=errors;(ROOT/'production/qa/evidence/redesign/classic-combat-restore/fallback-reduced.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');c.close();b.close();print(result)
